def creer_types_et_categories(apps, schema_editor):
    TypeSaisie, TypeReponse = apps.get_model("parametres", "TypeSaisie"), apps.get_model("parametres", "TypeReponse")
    Categorie = apps.get_model("parametres", "CategorieDescription")
    if not TypeSaisie.objects.exists():
        for i, (code, libelle, abrege, c, fond, texte, comportement) in enumerate(TYPES_SAISIE, start=1):
            TypeSaisie.objects.create(code=code, libelle=libelle, abrege=abrege, couleur=c, couleur_fond=fond, couleur_texte=texte,
                                      comportement=comportement, ordre=i)
    if not TypeReponse.objects.exists():
        for i, (code, libelle, fmt) in enumerate(TYPES_REPONSE, start=1):
            TypeReponse.objects.create(code=code, libelle=libelle, format=fmt, ordre=i)
    if not Categorie.objects.exists():
        for i, (code, libelle) in enumerate(CATEGORIES, start=1):
            Categorie.objects.create(code=code, libelle=libelle, ordre=i, affichee=True)


